begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users (id) values ('71000000-0000-4000-8000-000000000001'), ('71000000-0000-4000-8000-000000000002'), ('71000000-0000-4000-8000-000000000003');
insert into organizations (id, name) values ('72000000-0000-4000-8000-000000000001', 'A'), ('72000000-0000-4000-8000-000000000002', 'B');
insert into establishments (id, organization_id, name, timezone) values ('73000000-0000-4000-8000-000000000001', '72000000-0000-4000-8000-000000000001', 'A1', 'UTC'), ('73000000-0000-4000-8000-000000000002', '72000000-0000-4000-8000-000000000001', 'A2', 'UTC'), ('73000000-0000-4000-8000-000000000003', '72000000-0000-4000-8000-000000000002', 'B1', 'UTC');
insert into memberships (organization_id, user_id, role) values ('72000000-0000-4000-8000-000000000001', '71000000-0000-4000-8000-000000000001', 'owner'), ('72000000-0000-4000-8000-000000000002', '71000000-0000-4000-8000-000000000002', 'owner'), ('72000000-0000-4000-8000-000000000001', '71000000-0000-4000-8000-000000000003', 'member');
insert into suppliers (id,organization_id,establishment_id,name,email,contact) values
 ('74000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','Origem','a@example.test','0011'),('74000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','Outro',null,null),('74000000-0000-4000-8000-000000000003','72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','Usado',null,null),('74000000-0000-4000-8000-000000000004','72000000-0000-4000-8000-000000000002','73000000-0000-4000-8000-000000000003','Externo',null,null);
insert into products(id,organization_id,establishment_id,name,unit,storage_condition) values ('75000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','Arroz','kg','ambient');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001',' Nova Horta ',' b@example.test ',' 0022 ')$$,'proprietário edita e normaliza');
select is((select name from suppliers where id='74000000-0000-4000-8000-000000000001'),'Nova Horta','nome atualizado');
select is((select contact from suppliers where id='74000000-0000-4000-8000-000000000001'),'0022','contato normalizado');
select is((select count(*) from entity_changes where entity_id='74000000-0000-4000-8000-000000000001'),3::bigint,'audita três alterações');
select is((select old_value from entity_changes where entity_id='74000000-0000-4000-8000-000000000001' and field='email'),'a@example.test','valor anterior auditado');
select ok((select bool_and(changed_by='71000000-0000-4000-8000-000000000001'::uuid and establishment_id='73000000-0000-4000-8000-000000000001'::uuid) from entity_changes where entity_id='74000000-0000-4000-8000-000000000001'),'autor e escopo auditados');
select lives_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001','Nova Horta','b@example.test','0022')$$,'reenvio equivalente');
select is((select count(*) from entity_changes where entity_id='74000000-0000-4000-8000-000000000001'),3::bigint,'reenvio não duplica auditoria');
select lives_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001','Nova Horta',' ','')$$,'opcionais podem ser limpos');
select ok((select email is null and contact is null from suppliers where id='74000000-0000-4000-8000-000000000001'),'opcionais vazios nulos');
select throws_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001','Outro',null,null)$$,'23505',null,'nome duplicado recusado');
select throws_ok($$select edit_supplier('72000000-0000-4000-8000-000000000002','73000000-0000-4000-8000-000000000003','74000000-0000-4000-8000-000000000004','Ataque',null,null)$$,'42501',null,'A não edita B');
select throws_ok($$select delete_supplier('72000000-0000-4000-8000-000000000002','73000000-0000-4000-8000-000000000003','74000000-0000-4000-8000-000000000004')$$,'42501',null,'A não exclui B');
select throws_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000002','74000000-0000-4000-8000-000000000001','Ataque',null,null)$$,'42501',null,'unidade errada recusada');
select throws_ok($$select delete_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000002','74000000-0000-4000-8000-000000000001')$$,'42501',null,'exclusão em unidade errada recusada');
select throws_ok($$update suppliers set contact='Ataque' where id='74000000-0000-4000-8000-000000000001'$$,'42501',null,'UPDATE direto continua negado');
select throws_ok($$delete from suppliers where id='74000000-0000-4000-8000-000000000001'$$,'42501',null,'DELETE direto continua negado');
select lives_ok($$select receive_batch('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','75000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000003','L1',1,'2027-01-01','original','2027-01-01','ambient','not_required',null,null,'76000000-0000-4000-8000-000000000001')$$,'recebimento referencia fornecedor');
select throws_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000003','Nome novo',null,null)$$,'22023',null,'nome usado não muda etiqueta histórica');
select lives_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000003','Usado','u@example.test','0033')$$,'contatos usados podem mudar');
select throws_ok($$select delete_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000003')$$,'23503',null,'FK protege fornecedor com recebimentos');
select is((select count(*) from entity_changes where entity_id='74000000-0000-4000-8000-000000000003' and field='deleted'),0::bigint,'exclusão recusada não gera auditoria falsa');
select is((select count(*) from batch_receipts where supplier_id='74000000-0000-4000-8000-000000000003'),1::bigint,'recebimento permanece');
select lives_ok($$select delete_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001')$$,'proprietário exclui fornecedor sem uso');
select is((select count(*) from suppliers where id='74000000-0000-4000-8000-000000000001'),0::bigint,'fornecedor removido da lista');
select is((select old_value::jsonb->>'name' from entity_changes where entity_id='74000000-0000-4000-8000-000000000001' and field='deleted'),'Nova Horta','snapshot preservado na auditoria');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000002','Ataque',null,null)$$,'42501',null,'colaborador não edita');
select throws_ok($$select delete_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000002')$$,'42501',null,'colaborador não exclui');
reset role;
update memberships set revoked_at=now() where user_id='71000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select delete_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000002')$$,'42501',null,'proprietário revogado não exclui');
set local role anon;
select throws_ok($$select edit_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000002','Ataque',null,null)$$,'42501',null,'anônimo sem EXECUTE de edição');
select throws_ok($$select delete_supplier('72000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000002')$$,'42501',null,'anônimo sem EXECUTE de exclusão');
reset role;
select ok((select not prosecdef from pg_proc where oid='public.edit_supplier(uuid,uuid,uuid,text,text,text)'::regprocedure),'wrapper público invoker');
select ok((select prosecdef from pg_proc where oid='private.edit_supplier(uuid,uuid,uuid,text,text,text)'::regprocedure),'implementação privada definer');
select * from finish();
rollback;
